package com.jb.radar;
public class UpdateTest {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[] args){Game g=new Game(19);g.start();g.contacts.clear();Game.Contact a=GameTest.target(g,0),b=GameTest.target(g,1);a.priority=false;g.illuminate(a);ok(!a.illuminated,"track required before lock");double ev=a.evasion;g.track(a);ok(a.priority&&a.evasion==ev&&g.channels()==0,"track without warning/channel");g.illuminate(a);ok(a.illuminated,"lock after track");ok(g.nextTarget(null)==a&&g.nextTarget(a)==b&&g.nextTarget(b)==a,"distance cycle");g.maxRange=27;int[] p=g.presets();ok(p.length==3&&p[2]==27,"damaged presets");g.range=10;ok(g.rangeQuality()==1,"short precision");g.range=40;ok(g.rangeQuality()==.7,"long precision");g.start();g.contacts.clear();a=GameTest.target(g,0);a.weapon=0;g.tryEnemyLaunch(a);ok(g.enemyMissiles.isEmpty(),"approach delay");g.elapsed=31;g.tryEnemyLaunch(a);ok(g.enemyMissiles.size()==1,"guided launch");Game.EnemyMissile m=g.enemyMissiles.get(0);a.alive=false;for(int i=0;i<40;i++)g.flyEnemy(m,.1);ok(!m.alive&&g.maxRange==40,"guidance source loss");g.start();g.contacts.clear();a=GameTest.target(g,0);a.weapon=-1;g.elapsed=90;g.tryEnemyLaunch(a);ok(g.enemyMissiles.isEmpty(),"no guided weapons");int previous=40;while(!g.finished){g.damageRadar();ok(previous-g.maxRange>=Math.min(2,previous)&&previous-g.maxRange<=8,"impact damage");previous=g.maxRange;}ok(g.finished&&!g.won&&g.health==0&&g.radarHits==4&&g.range>0,"range zero failure/render guard");System.out.println("PASS: track/lock separation, sorted cycle, range precision/damage presets, launch delay, source guidance, unarmed contact, cumulative destruction");}
}
